import java.util.*;

public class Main {
    static final long mod = 998244353;
    static final int N = 5000;
    static int[][] factor = new int[N + 1][];
    static List<Long> primes = new ArrayList<>();

    static long comb(int m, int n) {
        long res = 1;
        int[] fnm = new int[primes.size()];
        System.arraycopy(factor[n], 0, fnm, 0, primes.size());
        for (int i = 0; i < factor[m].length; i++) {
            fnm[i] += factor[m][i];
        }
        for (int w = 1; w <= m; w++) {
            long r = 1;
            for (int i = 0; i < primes.size(); i++) {
                long p = primes.get(i);
                for (int pw = fnm[i] - factor[w][i] - factor[n - w][i] - factor[m - w][i]; pw > 0; pw >>= 1) {
                    if ((pw & 1) == 1) {
                        r = r * p % mod;
                    }
                    p = p * p % mod;
                }
            }
            res += r;
        }
        return res % mod;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int[] abc = new int[]{0, 0, 0};
        abc[0] = sc.nextInt();
        abc[1] = sc.nextInt();
        abc[2] = sc.nextInt();
        Arrays.sort(abc);
        boolean[] sieve = new boolean[N + 1];
        sieve[0] = true;
        sieve[1] = true;
        for (int p = 0; p < sieve.length; p++) {
            if (!sieve[p]) {
                primes.add((long) p);
                for (int q = p * p; q <= N; q += p) {
                    sieve[q] = true;
                }
            }
        }
        for (int j = 0; j < factor.length; j++) {
            factor[j] = new int[primes.size()];
        }
        for (int i = 0; i < primes.size(); i++) {
            long p = primes.get(i);
            for (long pp = p; pp <= N; pp *= p) {
                for (long j = pp; j <= N; j += pp) {
                    factor[(int) j][i]++;
                }
            }
        }
        int[] a = factor[0];
        for (int[] b : factor) {
            for (int i = 0; i < a.length; i++) {
                b[i] += a[i];
            }
            a = b;
        }
        System.out.println(comb(abc[0], abc[1]) * comb(abc[0], abc[2]) % mod * comb(abc[1], abc[2]) % mod);
    }
}
